<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Terms of Use Consent</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f4f7fb;
      --surface: #ffffff;
      --surface-2: #f8fafc;
      --text: #102033;
      --muted: #5f6b7a;
      --border: #ced8e3;
      --accent: #2457ff;
      --accent-strong: #1c44cc;
      --accent-soft: rgba(36, 87, 255, 0.12);
      --success: #0f7a3a;
      --error: #b42318;
      --shadow: 0 24px 60px rgba(16, 32, 51, 0.12);
      --radius: 20px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      background:
        radial-gradient(circle at top, rgba(36, 87, 255, 0.10), transparent 40%),
        linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
      color: var(--text);
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
    }

    main {
      width: min(100%, 480px);
    }

    .card {
      background: var(--surface);
      border: 1px solid rgba(206, 216, 227, 0.85);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
      padding: 32px;
    }

    h1 {
      margin: 0 0 12px;
      font-size: clamp(1.6rem, 4vw, 2.1rem);
      line-height: 1.15;
      letter-spacing: -0.03em;
    }

    .intro {
      margin: 0 0 28px;
      color: var(--muted);
      line-height: 1.55;
    }

    form {
      display: grid;
      gap: 20px;
    }

    .form-field {
      padding: 18px;
      border-radius: 16px;
      background: var(--surface-2);
      border: 1px solid var(--border);
    }

    .consent-row {
      display: flex;
      gap: 14px;
      align-items: flex-start;
    }

    .checkbox-wrap {
      position: relative;
      flex: none;
      width: 22px;
      height: 22px;
      margin-top: 2px;
    }

    input[type="checkbox"] {
      width: 22px;
      height: 22px;
      margin: 0;
      appearance: none;
      border: 2px solid #99a8b8;
      border-radius: 6px;
      background: #fff;
      display: grid;
      place-content: center;
      transition: border-color 140ms ease, background-color 140ms ease, box-shadow 140ms ease;
      cursor: pointer;
    }

    input[type="checkbox"]::before {
      content: "";
      width: 10px;
      height: 6px;
      border: 2px solid transparent;
      border-top: 0;
      border-right: 0;
      transform: rotate(-45deg) scale(0);
      transition: transform 140ms ease;
      border-color: #ffffff;
      margin-top: -1px;
    }

    input[type="checkbox"]:checked {
      border-color: var(--accent);
      background: var(--accent);
    }

    input[type="checkbox"]:checked::before {
      transform: rotate(-45deg) scale(1);
    }

    input[type="checkbox"]:focus-visible {
      outline: 3px solid var(--accent-soft);
      outline-offset: 3px;
      box-shadow: 0 0 0 1px var(--accent);
    }

    label {
      font-weight: 600;
      line-height: 1.45;
      cursor: pointer;
    }

    .required-mark {
      color: var(--accent-strong);
      margin-left: 2px;
    }

    .help {
      margin: 8px 0 0 36px;
      color: var(--muted);
      font-size: 0.95rem;
      line-height: 1.45;
    }

    .status {
      min-height: 1.5em;
      margin: 0;
      font-size: 0.95rem;
      line-height: 1.45;
    }

    .status[data-state="error"] {
      color: var(--error);
    }

    .status[data-state="success"] {
      color: var(--success);
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.95rem 1.25rem;
      background: linear-gradient(180deg, #2f66ff, var(--accent));
      color: #fff;
      font: inherit;
      font-weight: 700;
      letter-spacing: 0.01em;
      cursor: pointer;
      box-shadow: 0 12px 24px rgba(36, 87, 255, 0.24);
      transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease;
    }

    button:hover {
      background: linear-gradient(180deg, #315fff, var(--accent-strong));
      box-shadow: 0 14px 28px rgba(36, 87, 255, 0.28);
    }

    button:active {
      transform: translateY(1px);
    }

    button:focus-visible {
      outline: 3px solid var(--accent-soft);
      outline-offset: 3px;
    }

    @media (max-width: 420px) {
      body {
        padding: 16px;
      }

      .card {
        padding: 24px;
      }

      .form-field {
        padding: 16px;
      }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        scroll-behavior: auto;
        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }
  </style>
</head>
<body>
  <main id="maincontent" tabindex="-1">
    <section class="card" aria-labelledby="page-title">
      <h1 id="page-title">Agree to the Terms of Use</h1>
      <p class="intro">Review the terms and confirm your consent to continue.</p>

      <form id="consent-form" novalidate>
        <div class="form-field">
          <div class="consent-row">
            <div class="checkbox-wrap">
              <input
                id="agree-terms"
                name="agreeTerms"
                type="checkbox"
                required
                aria-describedby="consent-help consent-status"
              >
            </div>
            <div>
              <label for="agree-terms">
                I agree to the Terms of Use <span class="required-mark" aria-hidden="true">*</span>
              </label>
              <p id="consent-help" class="help">Required to create your account.</p>
            </div>
          </div>
        </div>

        <p id="consent-status" class="status" aria-live="polite"></p>

        <button type="submit">Continue</button>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('consent-form');
    const checkbox = document.getElementById('agree-terms');
    const status = document.getElementById('consent-status');

    form.addEventListener('submit', (event) => {
      event.preventDefault();

      if (!checkbox.checked) {
        checkbox.setAttribute('aria-invalid', 'true');
        status.textContent = 'Error: You must agree to the Terms of Use to continue.';
        status.dataset.state = 'error';
        checkbox.focus();
        return;
      }

      checkbox.removeAttribute('aria-invalid');
      status.textContent = 'Thanks — your consent has been recorded.';
      status.dataset.state = 'success';
      form.reset();
      checkbox.focus();
    });

    checkbox.addEventListener('change', () => {
      if (checkbox.checked) {
        checkbox.removeAttribute('aria-invalid');
        if (status.dataset.state === 'error') {
          status.textContent = '';
          delete status.dataset.state;
        }
      }
    });
  </script>
</body>
</html>
